import React from "react";
import { Link, useParams } from "react-router-dom";
import ChatWindow from "../../components/chat/ChatWindow";
import { useApp } from "../../lib/AppContext";

export default function ChatPage() {
  const { id } = useParams();
  const { reports } = useApp();
  const report = reports.find((item) => item.id === id);
  if (!report)
    return (
      <div className="empty-page">
        <h2>Report not found</h2>
        <Link className="secondary" to="/reports">
          Back to reports
        </Link>
      </div>
    );
  return (
    <>
      <div className="page-heading">
        <div>
          <div className="eyebrow">CITIZEN COMMUNICATION</div>
          <h1>Case conversation</h1>
          <p>Keep the reporter updated as the case progresses.</p>
        </div>
        <Link className="secondary" to={`/reports/${report.id}`}>
          ← Back to case
        </Link>
      </div>
      <ChatWindow report={report} />
    </>
  );
}
